<?php
declare(strict_types=1);require dirname(__DIR__).'/lib/bootstrap.php';require dirname(__DIR__).'/lib/admin.php';require dirname(__DIR__).'/lib/analytics.php';require dirname(__DIR__).'/lib/repository.php';require dirname(__DIR__).'/lib/view.php';$pdo=db();$new=search_items($pdo,['sort'=>'new'],10,0);$popular=search_items($pdo,['sort'=>'popular'],10,0);$high=search_items($pdo,['sort'=>'review','min_review'=>'4'],10,0);$free=search_items($pdo,['sort'=>'reviews','free_shipping'=>1],10,0);$cats=categories($pdo);public_header($pdo,'',site_description($pdo));?><section class="hero"><h1>楽天市場の大人向けグッズを、見やすく比較</h1><p><?=h(site_description($pdo))?></p><form class="searchbox" action="search.php"><input name="q" placeholder="商品名・キーワード"><select name="min_review"><option value="">評価指定なし</option><option value="4">★4.0以上</option><option value="4.5">★4.5以上</option></select><select name="sort"><option value="popular">PinkClub人気</option><option value="reviews">レビュー件数</option><option value="price_asc">価格が安い順</option></select><button>検索する</button></form></section><?php foreach([['新着商品',$new],['PinkClub人気商品',$popular],['高評価商品',$high],['送料無料商品',$free]] as [$label,$items]):?><section class="section"><div class="section-head"><h2><?=h($label)?></h2><a href="search.php">もっと見る</a></div><div class="grid"><?php foreach($items as $item)item_card($item);?></div></section><?php endforeach;?><section class="section"><div class="section-head"><h2>カテゴリから探す</h2><a href="categories.php">すべて見る</a></div><div class="category-grid"><?php foreach(array_slice($cats,0,12) as $c):?><a href="category.php?slug=<?=urlencode((string)$c['slug'])?>"><strong><?=h((string)$c['name'])?></strong><br><small><?=number_format((int)$c['item_count'])?>商品</small></a><?php endforeach;?></div></section><section class="section"><div class="section-head"><h2>楽天人気ランキング</h2><a href="ranking.php">ランキングを見る</a></div><?php $r=$pdo->query('SELECT * FROM rakuten_rankings WHERE genre_id=0 ORDER BY rank_no LIMIT 10')->fetchAll();?><div class="grid"><?php foreach($r as $row):?><article class="card"><a href="<?=h((string)($row['affiliate_url']?:$row['item_url']))?>" target="_blank" rel="nofollow sponsored noopener"><?php if($row['image_url']):?><img loading="lazy" src="<?=h((string)$row['image_url'])?>" alt="<?=h((string)$row['item_name'])?>"><?php endif?><h3><?=h((string)$row['rank_no'])?>位 <?=h((string)$row['item_name'])?></h3><div class="price">¥<?=number_format((int)$row['item_price'])?></div></a></article><?php endforeach;?></div></section><?php render_analytics_beacon();public_footer();
